// mount(source, target, filesystemtype, flags, data)

const char *device = "/dev/sdb1";
const char *mnt_path = "/mnt/data";
unsigned long flags = MS_NOATIME | MS_NODEV;

// 1. Standard Mount
int res_std = mount(device, mnt_path, "ext4", flags, "iocharset=utf8");

// 2. Remounting (Changing existing mount options)
// Source and fstype are usually ignored/NULL for remounts
int res_remount = mount(NULL, mnt_path, NULL,
                        MS_REMOUNT | MS_RDONLY, NULL);

// 3. Bind Mount (Mirroring a directory tree)
int res_bind = mount("/etc/config", "/tmp/etc_mirror",
                     NULL, MS_BIND, NULL);
